#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

int main() {
    long long n;
    cin >> n;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    long long hi = a[0], lo = a[0], best = a[0];
    for (int i = 1; i < n; i++) {
        long long x = a[i], p = hi * x, q = lo * x;
        hi = max(x, max(p, q));
        lo = min(x, min(p, q));
        best = max(best, hi);
    }
    cout << best << "\n";

    return 0;
}

code.java:
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        long[] a = new long[(int) n];
        for (int i = 0; i < a.length; i++) a[i] = sc.nextLong();

        long hi = a[0], lo = a[0], best = a[0];
        for (int i = 1; i < n; i++) {
            long x = a[i], p = hi * x, q = lo * x;
            hi = Math.max(x, Math.max(p, q));
            lo = Math.min(x, Math.min(p, q));
            best = Math.max(best, hi);
        }
        System.out.println(best);
    }
}
